    '\n    *[_type in ["page", "homePage", "blogPost", "event", "teamMember"] && (\n      defined(slug.current) || _type == "homePage"\n    )] {\n      _id,\n      _type,\n      title,\n      personName,\n      slug,\n      navigationName,\n      metaDescription,\n      eventDescription,\n      location,\n      \n      // Get all pageLayout data (all components)\n      pageLayout,\n      \n      // Team member bio\n      bio,\n    }\n  ': IndexQueryResult;
